// /sitemap.xml — generated by Next. Destination slugs come from the API; if the
// backend is unreachable at build time we still emit the static routes instead
// of failing the build.
const SITE = process.env.SITE_URL || 'http://localhost:3000';
const API = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000';

export default async function sitemap() {
  const now = new Date();
  const staticRoutes = ['', '/destinations', '/map'].map((path) => ({
    url: `${SITE}${path}`,
    lastModified: now,
    changeFrequency: 'weekly',
    priority: path === '' ? 1 : 0.8,
  }));

  let slugs = [];
  try {
    const res = await fetch(`${API}/api/destinations`, { next: { revalidate: 3600 } });
    if (res.ok) {
      const data = await res.json();
      slugs = (data.destinations || []).map((d) => d.slug);
    }
  } catch (e) {
    console.warn('[sitemap] API unreachable, emitting static routes only');
  }

  return [
    ...staticRoutes,
    ...slugs.map((slug) => ({
      url: `${SITE}/destination/${slug}`,
      lastModified: now,
      changeFrequency: 'monthly',
      priority: 0.7,
    })),
  ];
}
